use std::{path::{Path,Component},fs};
use crate::Project;
pub fn valid_asset(rel:&str)->bool{rel.starts_with("assets/")&&!rel.contains('\\')&&Path::new(rel).components().all(|c|matches!(c,Component::Normal(_)))&&rel.len()>7}
pub fn move_asset(root:&Path,p:&mut Project,old:&str,new:&str)->Result<(),String>{if !valid_asset(old)||!valid_asset(new){return Err("Invalid asset path".into());}let from=root.join(old);let to=root.join(new);if from==to{return Ok(());}if to.exists(){return Err("Destination already exists".into());}let base=root.join("assets").canonicalize().map_err(|e|e.to_string())?;if !from.canonicalize().map_err(|e|e.to_string())?.starts_with(&base){return Err("Source outside assets".into());}let parent=to.parent().ok_or("Missing parent")?;if !parent.exists(){return Err("Create destination folder first".into());}if !parent.canonicalize().map_err(|e|e.to_string())?.starts_with(&base){return Err("Destination outside assets".into());}fs::rename(from,to).map_err(|e|e.to_string())?;for o in &mut p.objects{if o.sprite.as_deref()==Some(old){o.sprite=Some(new.into());}}Ok(())}
pub fn import_folder(source:&Path,root:&Path)->Result<usize,String>{let root=root.canonicalize().map_err(|e|e.to_string())?;let source=source.canonicalize().map_err(|e|e.to_string())?;if root.starts_with(&source){return Err("Choose a folder outside the project".into());}let dest=root.join("assets").join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(&dest).map_err(|e|e.to_string())?;fn copy(src:&Path,dst:&Path,n:&mut usize)->Result<(),String>{for entry in fs::read_dir(src).map_err(|e|e.to_string())?{let entry=entry.map_err(|e|e.to_string())?;let t=entry.file_type().map_err(|e|e.to_string())?;let p=entry.path();let d=dst.join(entry.file_name());if t.is_dir(){fs::create_dir_all(&d).map_err(|e|e.to_string())?;copy(&p,&d,n)?;}else if t.is_file()&&p.extension().and_then(|x|x.to_str()).is_some_and(|x|matches!(x.to_lowercase().as_str(),"png"|"jpg"|"jpeg")){fs::copy(p,d).map_err(|e|e.to_string())?;*n+=1;}}Ok(())}let mut n=0;copy(&source,&dest,&mut n)?;Ok(n)}
#[cfg(test)]mod tests{use super::*;#[test]fn paths(){assert!(valid_asset("assets/hero.png"));assert!(!valid_asset("assets/../hero.png"));assert!(!valid_asset("assets/a\\b.png"));}}
